logicObject.source:
function (payload) {
                var request = new SpinRequest.Payload();
                request.header = this.createHeader();
                request.totalStake = payload.betAmount.value;
                if (payload.forceResult) {
                    request.forceData = this.createForceData();
                    this.fillForceData(request.forceData, payload.forceResult);
                }
                if (payload.replay) {
                    request.replayData = this.createReplayData();
                    this.fillReplayData(request.replayData, payload.replay);
                }
                if (payload.currencyMultiplier != null) {
                    request.accountData = new SG.GLM.Core.AccountData();
                    request.accountData.currencyMultiplier = payload.currencyMultiplier;
                }
                request.paylineCount = null;
                request.isFunDial = payload.funDialActive ? 1 : 0; // TODO - Replace this with fundial status from client
                return request;
            }

terminal.source:
function (spinResult, gameResult) {
                // Free rounds does not update balance until the end.
                var platform = RS.IPlatform.get();
                if (platform instanceof SG.Environment.Platform) {
                    var freeRoundsInfo = platform.freeRoundsInfo.value;
                    if (freeRoundsInfo && SG.Environment.FreeRoundsInfo.isOpen(freeRoundsInfo)) {
                        return false;
                    }
                }
                // Max win spin should always be the last spin.
                if (this.models.state.isMaxWin) {
                    return true;
                }
                // Balance frozen until last spin.
                if (spinResult.index < this.models.spinResults.length - 1) {
                    return false;
                }
                // Balance frozen during freespins.
                if (this.models.freeSpins.remaining > 0) {
                    return false;
                }
                // Base game spin or last free spin; show final balance after
                return true;
            }

closeGate.source:
function () {
                if (this.replayEngine.isReplay) {
                    return false;
                }
                if (!this.settings.closeRequest) {
                    return false;
                }
                if (this.models.freeSpins.remaining > 0 && !this.models.state.isMaxWin) {
                    // No close requests should be sent during free spins unless max win has been triggered.
                    return false;
                }
                return true;
            }

freeState.source:
function (fsInfo) {
                this.models.freeSpins.used = (fsInfo.freeSpinNumber != null ? fsInfo.freeSpinNumber : fsInfo.spinsUsed) || 0;
                this.models.freeSpins.isFreeSpins = this.models.freeSpins.used > 0;
                this.models.freeSpins.remaining = (fsInfo.freeSpinsTotal != null ? (fsInfo.freeSpinsTotal - this.models.freeSpins.used) : fsInfo.spinsRemaining) || 0;
                this.models.freeSpins.winAmount = fsInfo.fsWinnings;
                this.models.freeSpins.extraSpinsAwarded = fsInfo.extraSpinsAwarded || 0;
            }

ownAfterResult.source:
function (data) {
                // Catch the state of the fun dial from the response
                if (data.bgInfo) {
                    this.models.funDialActive = data.bgInfo.isFunDial;
                    // Set the correct stake information (used when recovering, otherwise it should be the same as it was when sending the request)
                    this.models.stake = this.models.stakeOptions[this.models.funDialActive ? 1 : 0];
                }
                // Call base version of the code
                _super.prototype.parseGameResult.call(this, data);
                // Handle anything else custom for our game
                // Super Dial Spin.
                if (data.magicWheel) {
                    this.models.feature.magicWheel = { type: RRMM.Models.Feature.Wheel.Type.MagicWheel, stopIndex: data.magicWheel.position };
                }
                else {
                    this.models.feature.magicWheel = undefined;
                }
                // Symbol Upgrades (Fairy Symbol)
                if (data.upgradeData) {
                    this.models.feature.freeSpins = {
                        type: RRMM.Models.Feature.FreeSpins.Type.FreeSpins,
                        upgradeSymbol: data.upgradeData.symbolID,
                        upgradePositions: __spreadArrays(data.upgradeData.upgradePositions)
                    };
                }
                else {
                    this.models.feature.freeSpins = undefined;
                }
            }

fillRequest.source:
function (payload) {
                var totalBet = RS.Slots.Models.Stake.toTotal(this.models.stake, payload.betAmount);
                totalBet.value /= this._currencyMultiplier;
                return {
                    currencyMultiplier: this._userSettings.currencyMultiplier,
                    betAmount: totalBet,
                    paylineCount: payload.paylineCount,
                    forceResult: this._force.shift(),
                    replay: this._replayEngine.replay,
                    funDialActive: this.models.funDialActive
                };
            }

